def column_totals(rows):
    if not rows:
        return []
    result = []
    for i in range(len(rows[0])):
        total = 0
        numeric_count = 0
        for r in rows:
            if isinstance(r[i], (int, float)):
                total += r[i]
                numeric_count += 1
        if numeric_count == 0:
            result.append("")
        else:
            result.append(total)
    return result

